/* ---- canonical graphite scale (Obsidian palette) ----------------------- */
--mc-void: #0b0e13;
--mc-canvas: #0e1319;
--mc-surface: #12171e;
--mc-surface-2: #1b222b;
--mc-surface-3: #212934;
--mc-surface-4: #283240;
--mc-border: rgba(195, 211, 228, 0.11);
--mc-border-strong: rgba(225, 237, 249, 0.20);
--mc-border-faint: rgba(195, 211, 228, 0.06);

/* ---- glassmorphism material tiers (Obsidian) --------------------------- */
--mc-glass-base: rgba(18, 23, 30, 0.76);
--mc-glass-raised: rgba(21, 27, 35, 0.82);
--mc-glass-card: rgba(17, 23, 31, 0.73);
--mc-glass-card-hover: rgba(26, 34, 44, 0.85);
--mc-glass-overlay: rgba(3, 6, 11, 0.65);
--mc-glass-popover: rgba(25, 32, 41, 0.97);

--mc-glass-border: rgba(195, 211, 228, 0.11);
--mc-glass-border-hover: rgba(225, 237, 249, 0.20);
--mc-glass-border-focus: #afc6f3;
--mc-glass-bevel: inset 0 1px 0 0 rgba(255, 255, 255, 0.08);
--mc-glass-bevel-subtle: inset 0 1px 0 0 rgba(255, 255, 255, 0.04);

--mc-blur-sm: 8px;
--mc-blur-md: 16px;
--mc-blur-lg: 24px;
--mc-blur-xl: 30px;

--mc-text: #eef2f6;
--mc-text-soft: #d3dce6;
--mc-text-muted: #b0bac6;
--mc-text-dim: #95a2b1;
--mc-text-ink: #192128;

/* ---- Obsidian semantic accents ----------------------------------------- */
--mc-accent: #a9ddc4;
--mc-accent-strong: #c2ecd8;
--mc-accent-soft: rgba(169, 221, 196, 0.12);
--mc-accent-line: rgba(169, 221, 196, 0.28);
--mc-accent-glow: rgba(169, 221, 196, 0.35);
--mc-accent-gradient: linear-gradient(135deg, #a9ddc4 0%, #76bfa0 100%);

--mc-ai: #afc6f3;
--mc-ai-strong: #c8d8f7;
--mc-ai-soft: rgba(175, 198, 243, 0.14);
--mc-ai-glow: rgba(175, 198, 243, 0.35);
--mc-ai-gradient: linear-gradient(135deg, #c8d8f7 0%, #afc6f3 100%);

--mc-ok: #a9ddc4;
--mc-ok-soft: rgba(169, 221, 196, 0.12);
--mc-ok-glow: rgba(169, 221, 196, 0.35);

--mc-warning: #edc58b;
--mc-warning-soft: rgba(237, 197, 139, 0.12);
--mc-warning-glow: rgba(237, 197, 139, 0.35);

--mc-danger: #f2a7ae;
--mc-danger-soft: rgba(242, 167, 174, 0.12);
--mc-danger-glow: rgba(242, 167, 174, 0.35);

--mc-info: #afc6f3;

/* ---- spacing / radius / motion / elevation -------------------------- */
--mc-space-1: 4px;  --mc-space-2: 8px;  --mc-space-3: 12px;
--mc-space-4: 16px; --mc-space-5: 20px; --mc-space-6: 24px;
--mc-space-8: 32px; --mc-space-10: 40px;

--mc-radius-2xs: 3px;
--mc-radius-xs: 5px;
--mc-radius-sm: 8px;
--mc-radius-md: 11px;
--mc-radius-lg: 16px;
--mc-radius-modal: 20px;
--mc-radius-pill: 999px;

--mc-shadow-1: 0 1px 2px rgba(0, 0, 0, .3);
--mc-shadow-2: 0 12px 40px rgba(0, 0, 0, .2), inset 0 1px 0 rgba(255, 255, 255, .03);
--mc-shadow-float: 0 30px 100px rgba(0, 0, 0, .65), inset 0 1px 0 rgba(255, 255, 255, .10);
--mc-focus-ring: 0 0 0 2px var(--mc-void), 0 0 0 4px rgba(175, 198, 243, 0.45);
--mc-glow-primary: 0 0 24px rgba(169, 221, 196, 0.28);

